 "content": "def transform(grid):
    """Extend the axis through each 3x3 marker and mark its rail crossings."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Markers are 3x3 frames of 3 surrounding a central 2.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3
                   for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                                  (r,c-1),(r,c+1),
                                  (r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r, c))

    # Long 2-lines are rails. Extend along the axis perpendicular to them.
    horizontal_rails = any(sum(v == 2 for v in row) >= 0.7 * w for row in grid)
    vertical_rails = any(sum(grid[r][c] == 2 for r in range(h)) >= 0.7 * h
                         for c in range(w))
    vertical_ray = horizontal_rails and not vertical_rails
    if not horizontal_rails and vertical_rails:
        vertical_ray = False
    elif horizontal_rails and vertical_rails:
        row_score = max(sum(v == 2 for v in row) / w for row in grid)
        col_score = max(sum(grid[r][c] == 2 for r in range(h)) / h for c in range(w))
        vertical_ray = row_score >= col_score

    for r, c in centers:
        ray = [(rr, c) for rr in range(h)] if vertical_ray else [(r, cc) for cc in range(w)]
        # The beam fills empty cells but leaves the existing frame and 2 rails intact.
        for rr, cc in ray:
            if out[rr][cc] == 0:
                out[rr][cc] = 1
        # At each 2 on the beam, paint a 3x3 patch, retaining its central 2
        # and any marker-frame cells (3).
        for rr, cc in ray:
            if grid[rr][cc] != 2:
                continue
            for pr in range(max(0, rr-1), min(h, rr+2)):
                for pc in range(max(0, cc-1), min(w, cc+2)):
                    if (pr, pc) != (rr, cc) and out[pr][pc] != 3:
                        out[pr][pc] = 1
    return out
